mapper.select:
select  from topic_route_session
where member_id=#{memberId} and topic_id=#{topicId}
and activity_id=#{activityId}
order by id desc

mapper.update:
update topic_route_session set phase=#{phase},update_time=#{updateTime}
where id=#{id} and member_id=#{memberId} and status=0
  and (phase is null or phase in ('PREPARED','RUNNING'))

update topic_route_session set status=#{status},phase=#{phase},completed_at=#{endedAt},
  current_node_id=null,recommended_node_id=null,version=version+1,update_time=#{endedAt}
where id=#{id} and member_id=#{memberId} and status=0

mapper.select:
select min(checkin_time) from player_node_progress
where member_id=#{memberId} and activity_id=#{activityId} and topic_id=#{topicId} and node_id=#{nodeId}
  and play_instance_id=#{playInstanceId} and status=1 and del_flag=0 and checkin_time >= #{since}
